DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_THELASTCITY' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_THELASTCITY_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_1','The Last City[NEWLINE]One-city survival and siege preparation[NEWLINE]Humanity Endures survival objective; conventional victory remains separate[NEWLINE][NEWLINE]Keep Last Light fed, housed and defensible through recurring invasions. Refugees, Provisions and Morale are real capacity decisions; the Dawn Initiative is a survival progression rather than an automatic standard Civilization victory.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_2','Found a defensible Last Light with useful food and production. Establish the Sanctuary District and a mixed defensive army. Check Housing and Provisions before accepting additional pressure on the population.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_3','Use the Council to balance refugees, rationing and infrastructure with the invasion schedule. Preserve participating Last Watch veterans, maintain ranged damage and repair capacity, and keep a reserve for a difficult Major Siege.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_4','Prepare the documented Dawn Initiative requirements and a viable Final Night defense before spending the resources. After Humanity Endures, use the expanded survival phase deliberately; an ordinary Science or Culture objective still needs its normal requirements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_5','- Local defensive bonuses reward a compact, well-positioned army.[NEWLINE]- Surviving Major Sieges develops the city and eligible veterans.[NEWLINE]- A single concentrated economic and defensive plan reduces ordinary expansion logistics.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_6','- Permanent expansion and ordinary conquest are deliberately restricted.[NEWLINE]- One city''s food, Housing, Provisions and Morale are strategic bottlenecks.[NEWLINE]- Success at the custom survival objective does not itself fulfill a normal victory condition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_7','- Pressure the capital''s productive tiles and force resource spending before a siege.[NEWLINE]- Use ranged support and sustained economic denial rather than feeding units into strong local defenses.[NEWLINE]- A conventional research or cultural race can demand a response that pure city defense does not supply.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_8','- Accepting refugees without considering capacity and supplies.[NEWLINE]- Assuming every newly trained Watch inherits old siege ranks.[NEWLINE]- Launching the final challenge as soon as a button is available without a prepared defense.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: Prepared local defense can make a short attacking potion difficult to convert into a decisive breach.[NEWLINE][NEWLINE]McPvP: A compact, closely watched city approach offers fewer poorly monitored objective locations, although one successful objective still matters.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: A city-targeted economic debuff strikes a very large share of the Sanctuary''s total economy.[NEWLINE][NEWLINE]Sol Intellect: A protected research leader can threaten a conventional victory without having to defeat the Sanctuary''s strongest defenses.');
