INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_BACKGROUND','Keep Last Light fed, housed and defensible through recurring invasions. Refugees, Provisions and Morale are real capacity decisions; the Dawn Initiative is a survival progression rather than an automatic standard Civilization victory.');
