INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_LEADER_TEXT_2','Found a defensible Last Light with useful food and production. Establish the Sanctuary District and a mixed defensive army. Check Housing and Provisions before accepting additional pressure on the population.[NEWLINE][NEWLINE]Use the Council to balance refugees, rationing and infrastructure with the invasion schedule. Preserve participating Last Watch veterans, maintain ranged damage and repair capacity, and keep a reserve for a difficult Major Siege.[NEWLINE][NEWLINE]Prepare the documented Dawn Initiative requirements and a viable Final Night defense before spending the resources. After Humanity Endures, use the expanded survival phase deliberately; an ordinary Science or Culture objective still needs its normal requirements.');
