INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THELASTCITY_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: Prepared local defense can make a short attacking potion difficult to convert into a decisive breach.[NEWLINE][NEWLINE]McPvP: A compact, closely watched city approach offers fewer poorly monitored objective locations, although one successful objective still matters.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: A city-targeted economic debuff strikes a very large share of the Sanctuary''s total economy.[NEWLINE][NEWLINE]Sol Intellect: A protected research leader can threaten a conventional victory without having to defeat the Sanctuary''s strongest defenses.');
